metadados.consulta_graphql:
query RepositoriosPopulares($primeiros: Int!, $cursor: String, $busca: String!) {
  rateLimit {
    limit
    cost
    remaining
    resetAt
  }
  search(query: $busca, type: REPOSITORY, first: $primeiros, after: $cursor) {
    repositoryCount
    pageInfo {
      hasNextPage
      endCursor
    }
    nodes {
      ... on Repository {
        nameWithOwner
        url
        stargazerCount
        issues(first: 1) {
          totalCount
        }
        issuesFechadas: issues(first: 1, states: CLOSED) {
          totalCount
        }
      }
    }
  }
}
